"use client";

import React, { useRef } from "react";
import { motion, useScroll, useTransform } from "motion/react";
import { ArrowRight } from "lucide-react";
import { cn } from "@/lib/utils";

export interface HorizontalScrollItem {
  id: string;
  title: string;
  category: string;
  image: string;
}

const DEFAULT_PROJECTS: HorizontalScrollItem[] = [
  {
    id: "1",
    title: "Autonomous Kinetics",
    category: "Generative Systems",
    image: "https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=800&q=80",
  },
  {
    id: "2",
    title: "Spatial Typography",
    category: "Creative Direction",
    image: "https://images.unsplash.com/photo-1511497584788-87676104235f?auto=format&fit=crop&w=800&q=80",
  },
  {
    id: "3",
    title: "Bioluminescent UI",
    category: "Design Engineering",
    image: "https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80",
  },
  {
    id: "4",
    title: "Quantum Soundscapes",
    category: "Audio Synthesis",
    image: "https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80",
  },
];

export function HorizontalScrollSection({
  items = DEFAULT_PROJECTS,
  className,
}: {
  items?: HorizontalScrollItem[];
  className?: string;
}) {
  const containerRef = useRef<HTMLDivElement>(null);

  const { scrollYProgress } = useScroll({
    container: containerRef,
  });

  const x = useTransform(scrollYProgress, [0, 1], ["0%", "-60%"]);

  return (
    <div
      data-slot="horizontal-scroll-section"
      className={cn(
        "relative w-full max-w-2xl mx-auto h-[480px] overflow-hidden rounded-3xl border border-neutral-200 dark:border-neutral-800 bg-neutral-950 shadow-2xl select-none",
        className
      )}
    >
      <div
        ref={containerRef}
        className="h-full overflow-y-auto"
      >
        <div className="relative h-[220vh]">
          {/* Sticky Camera Container */}
          <div className="sticky top-0 h-[480px] flex flex-col justify-between p-8 overflow-hidden">
            {/* Header info */}
            <div className="flex items-center justify-between z-10">
              <div>
                <span className="text-[10px] font-mono font-bold uppercase tracking-widest text-pink-500">
                  Case Studies
                </span>
                <h3 className="text-xl font-bold tracking-tight text-white mt-0.5">
                  Horizontal Camera Pan
                </h3>
              </div>
              <div className="flex items-center gap-1.5 text-xs text-neutral-400 font-mono">
                <span>Scroll down</span>
                <ArrowRight className="h-3.5 w-3.5 animate-pulse" />
              </div>
            </div>

            {/* Horizontal Track of Cards */}
            <motion.div
              style={{ x }}
              className="flex gap-6 will-change-transform py-4"
            >
              {items.map((item) => (
                <div
                  key={item.id}
                  className="group relative h-64 w-80 shrink-0 overflow-hidden rounded-3xl border border-white/10 bg-neutral-900 shadow-xl"
                >
                  {/* eslint-disable-next-line @next/next/no-img-element */}
                  <img
                    src={item.image}
                    alt={item.title}
                    className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-105"
                  />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent" />
                  <div className="absolute bottom-5 left-5 right-5 text-white">
                    <span className="text-[10px] font-mono uppercase tracking-wider text-pink-400 font-bold">
                      {item.category}
                    </span>
                    <h4 className="text-base font-bold tracking-tight mt-0.5">
                      {item.title}
                    </h4>
                  </div>
                </div>
              ))}
            </motion.div>

            <div className="text-[11px] text-neutral-500 font-mono">
              Sticky scroll translating vertical movement to horizontal transform
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
